class Solution:
    def minSwaps(self, s: str) -> int:
        n = len(s)
        ones = s.count('1')
        zeros = n - ones
        if abs(ones - zeros) > 1:
            return -1

        def swaps(first):
            if (first == '1' and ones != (n + 1) // 2) or (first == '0' and zeros != (n + 1) // 2):
                return -1
            mis = 0
            expected = first
            for ch in s:
                if ch != expected:
                    mis += 1
                expected = '0' if expected == '1' else '1'
            return mis // 2

        results = [r for r in (swaps('0'), swaps('1')) if r != -1]
        return min(results) if results else -1

