class Solution {
public:
    int minSwaps(string s) {
        int n = s.size();
        int ones = count(s.begin(), s.end(), '1');
        int zeros = n - ones;
        if (abs(ones - zeros) > 1) return -1;
        auto cost = [&](char first) -> int {
            int have = (first == '1') ? ones : zeros;
            if (have != (n + 1) / 2) return -1;
            int mis = 0;
            char expected = first;
            for (char ch : s) {
                if (ch != expected) ++mis;
                expected = (expected == '1') ? '0' : '1';
            }
            return mis / 2;
        };
        int best = INT_MAX;
        for (char first : {'0', '1'}) {
            int c = cost(first);
            if (c != -1) best = min(best, c);
        }
        return best == INT_MAX ? -1 : best;
    }
};

