class Solution {
    public int minSwaps(String s) {
        int n = s.length();
        int ones = 0;
        for (char ch : s.toCharArray()) if (ch == '1') ones++;
        int zeros = n - ones;
        if (Math.abs(ones - zeros) > 1) return -1;
        int best = Integer.MAX_VALUE;
        for (char first : new char[]{'0', '1'}) {
            int have = first == '1' ? ones : zeros;
            if (have != (n + 1) / 2) continue;
            int mis = 0;
            char expected = first;
            for (char ch : s.toCharArray()) {
                if (ch != expected) mis++;
                expected = expected == '1' ? '0' : '1';
            }
            best = Math.min(best, mis / 2);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

