    const n = s.length;
    const ones = [...s].filter(c => c === '1').length;
    const zeros = n - ones;
    if (Math.abs(ones - zeros) > 1) return -1;
    const swaps = (first) => {
        if ((first === '1' ? ones : zeros) !== Math.floor((n + 1) / 2)) return Infinity;
        let mis = 0;
        let expected = first;
        for (const ch of s) {
            if (ch !== expected) mis++;
            expected = expected === '1' ? '0' : '1';
        }
        return mis >> 1;
    };
    return Math.min(swaps('0'), swaps('1'));
};

