    int minSwaps(string s) {
        int n = s.size(), ones = 0;
        for (char c : s) ones += (c == '1');
        int zeros = n - ones;
        if (abs(ones - zeros) > 1) return -1;
        int onesAtOdd = 0;
        for (int i = 0; i < n; ++i)
            if (s[i] == '1' && (i & 1)) ++onesAtOdd;
        int onesAtEven = ones - onesAtOdd;
        if (ones == zeros) return min(onesAtEven, onesAtOdd);
        return ones > zeros ? onesAtOdd : onesAtEven;
    }
};

